CREATE OR REPLACE FUNCTION nexus.search_metadata_scoped_384( p_query nexus.vector(384), p_collections text[], p_content_type text, p_author text, p_year int, p_corpus text, p_subtree text, p_where jsonb, p_n int ) RETURNS TABLE(id text, content text, collection text, distance float8, chash text, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT d.tumbler, c.chunk_text, c.collection, (c.embedding_384 OPERATOR(nexus.<=>) p_query)::float8, encode(c.chash, 'hex'), c.retention FROM nexus.chunks c JOIN nexus.catalog_document_chunks m ON m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE c.collection = ANY(p_collections) AND d.deleted_at IS NULL AND (p_content_type IS NULL OR d.content_type = p_content_type) AND (p_author IS NULL OR d.author ILIKE '%' || p_author || '%') AND (p_year IS NULL OR d.year = p_year) AND (p_corpus IS NULL OR d.corpus = p_corpus) AND d.alias_of = '' AND (p_subtree IS NULL OR d.tumbler LIKE p_subtree || '.%') AND (p_where IS NULL OR c.metadata @> p_where) AND c.embedding_384 IS NOT NULL ORDER BY c.embedding_384 OPERATOR(nexus.<=>) p_query LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.search_metadata_scoped_768( p_query nexus.vector(768), p_collections text[], p_content_type text, p_author text, p_year int, p_corpus text, p_subtree text, p_where jsonb, p_n int ) RETURNS TABLE(id text, content text, collection text, distance float8, chash text, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT d.tumbler, c.chunk_text, c.collection, (c.embedding_768 OPERATOR(nexus.<=>) p_query)::float8, encode(c.chash, 'hex'), c.retention FROM nexus.chunks c JOIN nexus.catalog_document_chunks m ON m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE c.collection = ANY(p_collections) AND d.deleted_at IS NULL AND (p_content_type IS NULL OR d.content_type = p_content_type) AND (p_author IS NULL OR d.author ILIKE '%' || p_author || '%') AND (p_year IS NULL OR d.year = p_year) AND (p_corpus IS NULL OR d.corpus = p_corpus) AND d.alias_of = '' AND (p_subtree IS NULL OR d.tumbler LIKE p_subtree || '.%') AND (p_where IS NULL OR c.metadata @> p_where) AND c.embedding_768 IS NOT NULL ORDER BY c.embedding_768 OPERATOR(nexus.<=>) p_query LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.search_metadata_scoped_1024( p_query nexus.vector(1024), p_collections text[], p_content_type text, p_author text, p_year int, p_corpus text, p_subtree text, p_where jsonb, p_n int ) RETURNS TABLE(id text, content text, collection text, distance float8, chash text, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT d.tumbler, c.chunk_text, c.collection, (c.embedding_1024 OPERATOR(nexus.<=>) p_query)::float8, encode(c.chash, 'hex'), c.retention FROM nexus.chunks c JOIN nexus.catalog_document_chunks m ON m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE c.collection = ANY(p_collections) AND d.deleted_at IS NULL AND (p_content_type IS NULL OR d.content_type = p_content_type) AND (p_author IS NULL OR d.author ILIKE '%' || p_author || '%') AND (p_year IS NULL OR d.year = p_year) AND (p_corpus IS NULL OR d.corpus = p_corpus) AND d.alias_of = '' AND (p_subtree IS NULL OR d.tumbler LIKE p_subtree || '.%') AND (p_where IS NULL OR c.metadata @> p_where) AND c.embedding_1024 IS NOT NULL ORDER BY c.embedding_1024 OPERATOR(nexus.<=>) p_query LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.search_graph_hop_384( p_query nexus.vector(384), p_seeds text[], p_collections text[], p_link_type text, p_depth int, p_direction text, p_where jsonb, p_n int ) RETURNS TABLE(id text, content text, collection text, distance float8, chash text, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ WITH RECURSIVE reach(tumbler, d) AS ( SELECT s, 0 FROM unnest(p_seeds) AS s UNION SELECT CASE WHEN l.from_tumbler = r.tumbler THEN l.to_tumbler ELSE l.from_tumbler END, r.d + 1 FROM reach r JOIN nexus.catalog_links l ON ((p_direction = 'out' AND l.from_tumbler = r.tumbler) OR (p_direction = 'in' AND l.to_tumbler = r.tumbler) OR (p_direction = 'both' AND (l.from_tumbler = r.tumbler OR l.to_tumbler = r.tumbler))) JOIN nexus.catalog_documents fd ON fd.tumbler = l.from_tumbler AND fd.deleted_at IS NULL JOIN nexus.catalog_documents td ON td.tumbler = l.to_tumbler AND td.deleted_at IS NULL WHERE r.d < p_depth AND (p_link_type IS NULL OR l.link_type = p_link_type) ), reached AS (SELECT DISTINCT tumbler FROM reach) SELECT d.tumbler, c.chunk_text, c.collection, (c.embedding_384 OPERATOR(nexus.<=>) p_query)::float8, encode(c.chash, 'hex'), c.retention FROM nexus.chunks c JOIN nexus.catalog_document_chunks m ON m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id JOIN reached rd ON rd.tumbler = d.tumbler WHERE c.collection = ANY(p_collections) AND d.deleted_at IS NULL AND (p_where IS NULL OR c.metadata @> p_where) AND c.embedding_384 IS NOT NULL ORDER BY c.embedding_384 OPERATOR(nexus.<=>) p_query LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.search_graph_hop_768( p_query nexus.vector(768), p_seeds text[], p_collections text[], p_link_type text, p_depth int, p_direction text, p_where jsonb, p_n int ) RETURNS TABLE(id text, content text, collection text, distance float8, chash text, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ WITH RECURSIVE reach(tumbler, d) AS ( SELECT s, 0 FROM unnest(p_seeds) AS s UNION SELECT CASE WHEN l.from_tumbler = r.tumbler THEN l.to_tumbler ELSE l.from_tumbler END, r.d + 1 FROM reach r JOIN nexus.catalog_links l ON ((p_direction = 'out' AND l.from_tumbler = r.tumbler) OR (p_direction = 'in' AND l.to_tumbler = r.tumbler) OR (p_direction = 'both' AND (l.from_tumbler = r.tumbler OR l.to_tumbler = r.tumbler))) JOIN nexus.catalog_documents fd ON fd.tumbler = l.from_tumbler AND fd.deleted_at IS NULL JOIN nexus.catalog_documents td ON td.tumbler = l.to_tumbler AND td.deleted_at IS NULL WHERE r.d < p_depth AND (p_link_type IS NULL OR l.link_type = p_link_type) ), reached AS (SELECT DISTINCT tumbler FROM reach) SELECT d.tumbler, c.chunk_text, c.collection, (c.embedding_768 OPERATOR(nexus.<=>) p_query)::float8, encode(c.chash, 'hex'), c.retention FROM nexus.chunks c JOIN nexus.catalog_document_chunks m ON m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id JOIN reached rd ON rd.tumbler = d.tumbler WHERE c.collection = ANY(p_collections) AND d.deleted_at IS NULL AND (p_where IS NULL OR c.metadata @> p_where) AND c.embedding_768 IS NOT NULL ORDER BY c.embedding_768 OPERATOR(nexus.<=>) p_query LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.search_graph_hop_1024( p_query nexus.vector(1024), p_seeds text[], p_collections text[], p_link_type text, p_depth int, p_direction text, p_where jsonb, p_n int ) RETURNS TABLE(id text, content text, collection text, distance float8, chash text, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ WITH RECURSIVE reach(tumbler, d) AS ( SELECT s, 0 FROM unnest(p_seeds) AS s UNION SELECT CASE WHEN l.from_tumbler = r.tumbler THEN l.to_tumbler ELSE l.from_tumbler END, r.d + 1 FROM reach r JOIN nexus.catalog_links l ON ((p_direction = 'out' AND l.from_tumbler = r.tumbler) OR (p_direction = 'in' AND l.to_tumbler = r.tumbler) OR (p_direction = 'both' AND (l.from_tumbler = r.tumbler OR l.to_tumbler = r.tumbler))) JOIN nexus.catalog_documents fd ON fd.tumbler = l.from_tumbler AND fd.deleted_at IS NULL JOIN nexus.catalog_documents td ON td.tumbler = l.to_tumbler AND td.deleted_at IS NULL WHERE r.d < p_depth AND (p_link_type IS NULL OR l.link_type = p_link_type) ), reached AS (SELECT DISTINCT tumbler FROM reach) SELECT d.tumbler, c.chunk_text, c.collection, (c.embedding_1024 OPERATOR(nexus.<=>) p_query)::float8, encode(c.chash, 'hex'), c.retention FROM nexus.chunks c JOIN nexus.catalog_document_chunks m ON m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id JOIN reached rd ON rd.tumbler = d.tumbler WHERE c.collection = ANY(p_collections) AND d.deleted_at IS NULL AND (p_where IS NULL OR c.metadata @> p_where) AND c.embedding_1024 IS NOT NULL ORDER BY c.embedding_1024 OPERATOR(nexus.<=>) p_query LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.search_topic_scoped_384( p_query nexus.vector(384), p_topic_label text, p_collection text, p_n int ) RETURNS TABLE(id text, content text, collection text, distance float8, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_384 OPERATOR(nexus.<=>) p_query)::float8, c.retention FROM nexus.chunks c JOIN nexus.topic_assignments ta ON ta.tenant_id = c.tenant_id AND ta.doc_id = c.chash JOIN nexus.topics t ON t.tenant_id = ta.tenant_id AND t.id = ta.topic_id WHERE c.collection = p_collection AND t.collection = p_collection AND t.label = p_topic_label AND c.embedding_384 IS NOT NULL AND (NOT EXISTS (SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash) OR EXISTS (SELECT 1 FROM nexus.catalog_document_chunks m JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash AND d.deleted_at IS NULL)) ORDER BY c.embedding_384 OPERATOR(nexus.<=>) p_query LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.search_topic_scoped_768( p_query nexus.vector(768), p_topic_label text, p_collection text, p_n int ) RETURNS TABLE(id text, content text, collection text, distance float8, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_768 OPERATOR(nexus.<=>) p_query)::float8, c.retention FROM nexus.chunks c JOIN nexus.topic_assignments ta ON ta.tenant_id = c.tenant_id AND ta.doc_id = c.chash JOIN nexus.topics t ON t.tenant_id = ta.tenant_id AND t.id = ta.topic_id WHERE c.collection = p_collection AND t.collection = p_collection AND t.label = p_topic_label AND c.embedding_768 IS NOT NULL AND (NOT EXISTS (SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash) OR EXISTS (SELECT 1 FROM nexus.catalog_document_chunks m JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash AND d.deleted_at IS NULL)) ORDER BY c.embedding_768 OPERATOR(nexus.<=>) p_query LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.search_topic_scoped_1024( p_query nexus.vector(1024), p_topic_label text, p_collection text, p_n int ) RETURNS TABLE(id text, content text, collection text, distance float8, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_1024 OPERATOR(nexus.<=>) p_query)::float8, c.retention FROM nexus.chunks c JOIN nexus.topic_assignments ta ON ta.tenant_id = c.tenant_id AND ta.doc_id = c.chash JOIN nexus.topics t ON t.tenant_id = ta.tenant_id AND t.id = ta.topic_id WHERE c.collection = p_collection AND t.collection = p_collection AND t.label = p_topic_label AND c.embedding_1024 IS NOT NULL AND (NOT EXISTS (SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash) OR EXISTS (SELECT 1 FROM nexus.catalog_document_chunks m JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash AND d.deleted_at IS NULL)) ORDER BY c.embedding_1024 OPERATOR(nexus.<=>) p_query LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.search_aspect_scoped_384( p_query nexus.vector(384), p_collections text[], p_field text, p_pattern text, p_min_confidence float8, p_where jsonb, p_n int ) RETURNS TABLE(id text, content text, collection text, distance float8, chash text, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT d.tumbler, c.chunk_text, c.collection, (c.embedding_384 OPERATOR(nexus.<=>) p_query)::float8, encode(c.chash, 'hex'), c.retention FROM nexus.chunks c JOIN nexus.catalog_document_chunks m ON m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id JOIN nexus.document_aspects a ON a.tenant_id = d.tenant_id AND a.doc_id = d.tumbler WHERE c.collection = ANY(p_collections) AND d.deleted_at IS NULL AND d.alias_of = '' AND c.embedding_384 IS NOT NULL AND (p_where IS NULL OR c.metadata @> p_where) AND (p_min_confidence IS NULL OR a.confidence >= p_min_confidence) AND (p_field IS NULL OR CASE p_field WHEN 'problem_formulation' THEN a.problem_formulation WHEN 'proposed_method' THEN a.proposed_method WHEN 'experimental_datasets' THEN a.experimental_datasets WHEN 'experimental_baselines' THEN a.experimental_baselines WHEN 'experimental_results' THEN a.experimental_results END ILIKE '%' || p_pattern || '%') ORDER BY c.embedding_384 OPERATOR(nexus.<=>) p_query LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.search_aspect_scoped_768( p_query nexus.vector(768), p_collections text[], p_field text, p_pattern text, p_min_confidence float8, p_where jsonb, p_n int ) RETURNS TABLE(id text, content text, collection text, distance float8, chash text, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT d.tumbler, c.chunk_text, c.collection, (c.embedding_768 OPERATOR(nexus.<=>) p_query)::float8, encode(c.chash, 'hex'), c.retention FROM nexus.chunks c JOIN nexus.catalog_document_chunks m ON m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id JOIN nexus.document_aspects a ON a.tenant_id = d.tenant_id AND a.doc_id = d.tumbler WHERE c.collection = ANY(p_collections) AND d.deleted_at IS NULL AND d.alias_of = '' AND c.embedding_768 IS NOT NULL AND (p_where IS NULL OR c.metadata @> p_where) AND (p_min_confidence IS NULL OR a.confidence >= p_min_confidence) AND (p_field IS NULL OR CASE p_field WHEN 'problem_formulation' THEN a.problem_formulation WHEN 'proposed_method' THEN a.proposed_method WHEN 'experimental_datasets' THEN a.experimental_datasets WHEN 'experimental_baselines' THEN a.experimental_baselines WHEN 'experimental_results' THEN a.experimental_results END ILIKE '%' || p_pattern || '%') ORDER BY c.embedding_768 OPERATOR(nexus.<=>) p_query LIMIT p_n $$;
